# Regenerates the iframe, downloadable HTML and document from one shared scenario.
from pathlib import Path
import json,shutil,runpy
root=Path(__file__).resolve().parents[2]
catalogue={c['id']:c for c in runpy.run_path(str(root/'backend/app/catalogue.py'))['COURSES']}
reasons={'AI101':'A practical starting point for a team new to workplace AI.','AI102':'Practise everyday productivity tasks and safe working habits.','AI103':'Build shared judgement around privacy, verification and responsible use.'}
fixture={'label':'Illustrative scripted scenario — not live AI','contact':{'name':'Alex Morgan','email':'alex@example.test','company':'Example organisation'},'requirements':{'goal':'AI confidence at work','team_size':15,'timeline_weeks':6,'experience':'beginner','format':'online'},'courses':[{'id':key,'title':catalogue[key]['title'],'reason':reason,'duration':catalogue[key]['duration'],'price_gbp':catalogue[key]['price_gbp'],'price':f"Illustrative £{catalogue[key]['price_gbp']} per learner"} for key,reason in reasons.items()]}
(root/'frontend/src/offlineScenario.json').write_text(json.dumps(fixture,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ABC SmartPath — Offline demo</title><style>*{box-sizing:border-box}body{margin:0;background:#fbfaf7;color:#283047;font-family:system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:30px}h1{font-size:38px;letter-spacing:-1.5px}h2{font-size:27px}p{line-height:1.7;font-size:14px}.notice{background:#f5ead4;border:1px solid #e4d5b7;padding:15px;border-radius:9px;font-size:12px}.steps{display:flex;gap:7px;margin:25px 0}.steps span{flex:1;border-bottom:3px solid #dfd9e8;font-size:10px;padding:10px 0}.steps .active{border-color:#805db2;color:#805db2;font-weight:bold}.panel{background:white;border:1px solid #e4deeb;padding:30px;border-radius:14px;min-height:360px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{background:#f0ebf7;border-radius:9px;padding:20px;font-size:12px}.card h3{font-size:18px}.button,button{background:#293149;color:white;border:0;border-radius:6px;padding:12px 18px;cursor:pointer;font:inherit;font-size:12px}button.secondary{background:#ece7f3;color:#504064}button:disabled{opacity:.4;cursor:default}.actions{display:flex;gap:10px;margin-top:20px;flex-wrap:wrap}input,textarea,select{display:block;border:1px solid #ddd5e5;padding:11px;border-radius:6px;margin:8px 0 15px;width:100%;font:inherit;font-size:13px}label{font-size:12px;display:block}.check{display:flex;gap:10px;align-items:center}.check input{width:auto;margin:0}.tag{color:#805db2;font-size:11px;font-weight:bold}.success{background:#e6efe8;padding:15px;border-radius:8px}pre{white-space:pre-wrap;line-height:1.7;font-family:inherit;font-size:13px}.muted{color:#837b8e;font-size:12px}@media(max-width:650px){main{padding:18px}.grid{grid-template-columns:1fr}.steps{flex-wrap:wrap}.steps span{min-width:25%}.panel{padding:20px}}</style><main><p class="tag">ABC SMARTPATH · OFFLINE DEMO</p><h1>A clearer path from ambition to action.</h1><p class="notice">Fully offline, scripted and illustrative. No live AI, retrieval, database writes or external emails. All contacts, matches, prices, approval and outbox content below are sample demonstration data. Restart clears this page's temporary state.</p><div class="steps" id="steps"></div><section class="panel" id="panel"></section><div class="actions"><button class="secondary" id="back">← Previous</button><button class="secondary" id="reset">Restart demo</button><button id="next">Begin journey →</button></div></main><script>
const fixture=FIXTURE;
const stages=['Your enquiry','Qualification','Course matches','Quote request','Staff review','Sample outbox'];let step=0,approved=false,consent=false,body='';
function render(){document.getElementById('steps').innerHTML=stages.map((s,i)=>'<span class="'+(i===step?'active':'')+'">'+(i+1)+'. '+s+'</span>').join('');document.getElementById('back').disabled=step===0;const next=document.getElementById('next');next.disabled=step===5;next.textContent=['Find my training path →','See suitable courses →','Get a quote →','Save sample enquiry →','Approve sample draft →','Demo complete'][step];
const p=document.getElementById('panel');if(step===0)p.innerHTML='<p class="tag">CUSTOMER EXPERIENCE</p><h2>What would you like to achieve?</h2><label>Your training goal<textarea id="goal" readonly>Our HR team needs practical AI training for 15 employees within six weeks.</textarea></label><p>No contact details needed to explore your options.</p><p class="muted">Fixed corporate scenario: read-only enquiry. Continue to explore the scripted customer and staff journey.</p>';
if(step===1)p.innerHTML='<p class="tag">ADAPTIVE GUIDANCE · SCRIPTED RESPONSE</p><h2>Let’s make the fit more precise.</h2><p>You have already told us: a team of 15, AI skills, within six weeks. We will not ask those questions again.</p><label>Current experience<input value="Beginner — new to workplace AI" readonly></label><label>Preferred delivery<input value="Online" readonly></label><p class="muted">Fixed scenario: these read-only requirements keep the demonstration on the beginner / online path. Use the live finder to explore different requirements.</p>';
if(step===2)p.innerHTML='<p class="tag">THREE ILLUSTRATIVE COURSE MATCHES</p><h2>Practical next steps for your team.</h2><div class="grid">'+fixture.courses.map(c=>'<article class="card"><p class="tag">'+c.id+'</p><h3>'+c.title+'</h3><p>'+c.reason+'</p><p>'+c.duration+'</p><strong>'+c.price+'</strong></article>').join('')+'</div><p class="muted">Scripted suitability explanations, not actual retrieval results. A real quote must confirm course availability and pricing.</p>';
if(step===3){p.innerHTML='<p class="tag">VALUE FIRST · CONTACT DETAILS AFTER MATCHES</p><h2>Request a quote for your team.</h2><label>Name<input value="Alex Morgan" readonly></label><label>Email<input value="alex@example.test" readonly></label><label>Company<input value="Example organisation" readonly></label><label class="check"><input id="consent" type="checkbox" '+(consent?'checked':'')+'> I agree to service contact about this sample enquiry.</label><p class="muted">Marketing consent stays off. No real lead will be created.</p>';next.disabled=!consent;document.getElementById('consent').onchange=e=>{consent=e.target.checked;next.disabled=!consent}}
if(step===4){p.innerHTML='<p class="success">Sample enquiry saved in this demo only. Reference: OFFLINE-DEMO-001</p><p class="tag">STAFF WORKSPACE · HUMAN APPROVAL</p><h2>Review before a commercial response.</h2><p><strong>High operational priority:</strong> explicit quote request, 15 employees, training within six weeks. This is a rule-based explanation, not a conversion prediction.</p><p class="muted">EXPERIMENTAL ML is separate; no score is asserted in this offline example.</p><label>Editable sample follow-up<textarea id="draft" rows="5"></textarea></label><p class="muted">Approval below adds only a sample message to the next offline screen. It does not send email.</p>';document.getElementById('draft').value=body||'Hello Alex, thank you for your enquiry about AI training for 15 colleagues within six weeks. We can discuss the introductory options and confirm availability, delivery and pricing before preparing a quote. Best wishes, ABC training team.';document.getElementById('draft').oninput=e=>body=e.target.value}
if(step===5){p.innerHTML='<p class="tag">SAMPLE LOCAL OUTBOX</p><h2>Approved by a person. Ready for the next step.</h2><p class="success">Sample approval recorded in this page only.</p><p><strong>To:</strong> alex@example.test<br><strong>Subject:</strong> Your team AI training enquiry</p><pre id="outbox"></pre><p class="muted">No external message was sent. Live ABC SmartPath stores staff decisions and local outbox records through authenticated backend APIs.</p>';document.getElementById('outbox').textContent=body||'Hello Alex, thank you for your enquiry about AI training for 15 colleagues within six weeks. We can discuss the introductory options and confirm availability, delivery and pricing before preparing a quote. Best wishes, ABC training team.'}}
document.getElementById('next').onclick=()=>{if(step===3&&!consent)return;if(step<5){step++;render()}};document.getElementById('back').onclick=()=>{step=Math.max(0,step-1);render()};document.getElementById('reset').onclick=()=>{step=0;consent=false;body='';render()};render();
</script></html>'''.replace('FIXTURE',json.dumps(fixture))
(root/'frontend/src/offlineDemo.html').write_text(html)
(root/'frontend/public').mkdir(exist_ok=True)
(root/'frontend/public/offline-demo.html').write_text(html)
old=root/'docs/Offline_Demo.html'
if old.exists() and not (root/'docs/Recorded_Screenshots.html').exists():shutil.copy2(old,root/'docs/Recorded_Screenshots.html')
old.write_text(html)
(root/'frontend/src/offlineDemo.jsx').write_text('''import React from 'react';
import offlineHtml from './offlineDemo.html?raw';
export function OfflineDemo(){return <main className="replay page"><div className="section-head"><div><p className="eyebrow">SELF-CONTAINED · SCRIPTED · NO LIVE SERVICES</p><h1 className="page-title">Offline demo</h1></div><a className="button secondary" href="/offline-demo.html" download="ABC_SmartPath_Offline_Demo.html">Save offline demo ↓</a></div><p>Walk through the corporate journey. You can save the HTML file and open it without internet, the backend or an LLM.</p><iframe title="Interactive offline corporate training demo" srcDoc={offlineHtml} style={{width:'100%',height:'1100px',border:'1px solid #e4deeb',borderRadius:12}} sandbox="allow-scripts"/></main>}
''')
